ruleToc.nextTocUrl:
#pagestats@textNodes
@js:
var nodes = result;
var totalPage = 0;
for (
var i = 0; i < nodes.length; i++) {
if (nodes[i].trim().startsWith('/')) {
totalPage = parseInt(nodes[i].trim().substring(1));
break;
}    
}
if (totalPage >= 10) {
java.toast('\n🔥共' + totalPage + '页目录，请耐心等待…🔥');
}
var data = [];
if (totalPage > 1) {
var basePart = baseUrl.replace(/_1\.html$/, '_');
for (
var i = 2; i <= totalPage; i++) {
data.push(basePart + i + '.html');
}
}
data

